document.querySelectorAll('[data-guide-copy]').forEach(button=>button.addEventListener('click',async()=>{const field=document.getElementById(button.dataset.guideCopy);try{await navigator.clipboard.writeText(field.value);button.textContent='✓ Đã sao chép';setTimeout(()=>button.textContent='📋 Sao chép mẫu lệnh',2000)}catch(error){field.focus();field.select();button.textContent='Đã chọn mẫu · nhấn Ctrl+C hoặc ⌘C để sao chép'}}));
document.addEventListener('click',event=>{const link=event.target.closest('a[href="#quiz-help"]');if(link){document.getElementById('quiz-help').open=true}});
</script>
